INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('bauwirtschaft-oesterreich-2026-fuenftes-jahr-rueckgang-branchenradar','Bauwirtschaft Österreich: Fünftes Jahr in Folge im Minus','Die Bauproduktion sinkt 2026 real um weitere drei Prozent. Vor allem der Wohnbau bricht ein, eine Trendwende erwarten Marktforscher erst 2028.','Die **Bauwirtschaft in Österreich** steuert 2026 auf das fünfte Jahr mit realem Rückgang in Folge zu. Das geht aus einer Analyse des Marktforschers Branchenradar hervor, die am 27. Oktober 2026 in Wien bei einer Pressekonferenz präsentiert wurde. Nominell sieht die Lage freundlicher aus, doch nach Abzug der Preissteigerungen schrumpft die Branche seit 2021 fast durchgehend.

## Bauwirtschaft Österreich: Mehr Umsatz, weniger Leistung

Der Produktionswert von Hoch- und Tiefbau ist laut Branchenradar zwischen 2020 und 2026 nominell um rund 22 Prozent gewachsen und dürfte heuer etwa 70,8 Milliarden Euro erreichen. Dieses Plus geht aber großteils auf höhere Preise zurück. Preisbereinigt liegt die gesamte Branche 2026 voraussichtlich rund zwölf Prozent unter dem Niveau von 2020.

Für das laufende Jahr erwarten die Marktforscher einen weiteren realen Rückgang der Bauproduktion um etwa drei Prozent. Wie schon in den Vorjahren kommt das Minus ausschließlich aus dem Hochbau. Der Tiefbau – also Straßen, Bahn, Leitungen und andere Infrastruktur – legt dagegen real um rund zwei Prozent zu.

## Baupreise um ein Drittel gestiegen

Ein wesentlicher Treiber der Entwicklung sind die Baupreise. Zwischen 2020 und 2025 haben sie sich im Hoch- und Tiefbau zusammen um etwa ein Drittel verteuert, im Hochbau um 38 Prozent und im Tiefbau um 26 Prozent. Die großen Sprünge fielen in die Jahre 2021 bis 2023. Zunächst waren es vor allem teurere Baumaterialien, später schlugen die höheren Personalkosten durch, nachdem die Inflation in den Kollektivvertragsverhandlungen abgegolten wurde.

## Wohnbau als Hauptgrund für den Einbruch

Bis 2025 ging der reale Rückgang laut der Analyse allein auf den Hochbau zurück, der um 16 Prozent schrumpfte. Verantwortlich dafür war praktisch nur der Wohnbau:

- Wohnungsneubau: minus 30 Prozent
- Renovierung im Wohnbau: minus 14 Prozent
- Nichtwohnbau (Büros, Gewerbe, Industrie): weitgehend stabil
- Tiefbau: real plus 12 Prozent

Besonders deutlich zeigt sich die Flaute bei den Bewilligungen. Die Zahl der zum Bau freigegebenen Wohnungen hat sich zwischen 2020 und 2025 mehr als halbiert. Die Baubeginne sanken im selben Zeitraum um 42 Prozent, die Fertigstellungen um 34 Prozent. Der Rückgang ist damit erst teilweise auf den Baustellen angekommen. Für 2026 rechnet Branchenradar mit einem weiteren Minus bei den Wohnbaugenehmigungen von rund fünf Prozent.

Im langfristigen Vergleich wurden 2025 nur noch 7,6 Wohneinheiten je 1.000 Privathaushalte genehmigt. 2017 waren es 18,5, im Jahr 2011 noch 12,9.

## Ursachen: Zinsen, Grundstückspreise und Vorschriften

Die Marktforscher sehen mehrere Gründe. Vor 2020 lagen die Bewilligungen über dem tatsächlichen Bedarf an Hauptwohnsitzen – unter anderem wegen der Flucht in Immobilien als Anlage während der Niedrigzinsphase, wegen touristisch genutzter Apartmenthäuser und mehr Nebenwohnsitzen. Danach bremsten gestiegene Zinsen, strengere Eigenmittelvorgaben bei Krediten, die hohen Baupreise sowie knapper werdendes und teureres Bauland. Dazu kommen aus Sicht von Branchenradar aufwendigere Bauverfahren und eine Übererfüllung von Normen und technischen Bauvorschriften, die über EU-Vorgaben hinausgeht.

Studienautor Andreas Kreutzer fordert deshalb eine rasche Deregulierung in allen Bereichen. Ohne Gegensteuern drohe der Wohnungsmarkt in naher Zukunft zu kollabieren, die Versorgung mit ausreichend Wohnraum sei gefährdet.

## Prognose: Trendwende frühestens 2028

Für 2027 veröffentlicht Branchenradar nur das günstigste Szenario: Dabei steigen die Baugenehmigungen bei allen Gebäudetypen wieder, und die reale Bauproduktion stabilisiert sich auf dem Niveau des Vorjahres. Wohnbau und Tiefbau würden jeweils um rund zwei Prozent wachsen, der Nichtwohnbau würde weiter nachgeben.

Die Trendwende für die Bauwirtschaft insgesamt erwarten die Marktforscher 2028. Für die Immobilienbranche und die Zahl der fertiggestellten Wohnungen sei ein Aufschwung dagegen frühestens 2029 zu erwarten. Wer eine Neubauwohnung sucht, muss sich also noch einige Jahre auf ein knappes Angebot einstellen.','wirtschaft','Konjunktur',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/bauwirtschaft-oesterreich-2026-fuenftes-jahr-rueckgang-branchenradar.webp','Branchenradar Marktanalyse via APA-OTS','https://www.ots.at/presseaussendung/OTS_20261027_OTS0076/bauwirtschaft-schrumpft-das-5-jahr-in-folge','published','2026-10-27T11:50:00.000Z','2026-10-27T11:44:54.583Z','Bauwirtschaft Österreich: 2026 das fünfte Minusjahr','Bauwirtschaft Österreich: Real 12 % unter 2020, Wohnbau bricht ein, Baupreise plus ein Drittel. Prognose und Ursachen laut Branchenradar im Überblick.','Bauwirtschaft Österreich','["Bauwirtschaft Österreich","Baukonjunktur 2026","Wohnbau Rückgang","Baupreise Österreich","Wohnbaugenehmigungen 2026","Branchenradar Bauwirtschaft Prognose","Bauproduktion Österreich 2027","Wohnungsmarkt Österreich Prognose"]','Stillstehende Wohnbau-Baustelle als Symbol für die schrumpfende Bauwirtschaft in Österreich','Half-finished residential concrete building shell in an Austrian suburb on an overcast autumn day, idle tower crane, empty scaffolding, puddles on the construction site, muted colors, wide shot, no people, no text, no logos, no readable signs','[{"q":"Wie stark schrumpft die Bauwirtschaft in Österreich 2026?","a":"Laut Branchenradar sinkt die Bauproduktion 2026 real um rund drei Prozent. Insgesamt liegt die Branche damit etwa zwölf Prozent unter dem Niveau von 2020."},{"q":"Warum geht der Wohnbau so stark zurück?","a":"Genannt werden höhere Zinsen, strengere Kreditvorgaben, um ein Drittel gestiegene Baupreise, teures Bauland sowie aufwendige Verfahren und Vorschriften."},{"q":"Wann wird eine Erholung erwartet?","a":"Die Bauwirtschaft insgesamt soll 2028 die Trendwende schaffen, bei Wohnungsfertigstellungen ist ein Aufschwung frühestens 2029 zu erwarten."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
